#!/usr/bin/env bash
# Writes Formula/webnak.rb for a release, from dist/checksums.txt.
#   VERSION=0.1.0 scripts/formula.sh
set -euo pipefail
cd "$(dirname "$0")/.."
V="${VERSION:?set VERSION}"
sum() { awk -v f="$1" '$2==f{print $1}' dist/checksums.txt; }
URL="https://github.com/sathninduk/webnak-cli/releases/download/v${V}"
mkdir -p Formula
cat > Formula/webnak.rb <<RUBY
# Generated by scripts/formula.sh for v${V}. Install with:
#   brew tap sathninduk/webnak https://github.com/sathninduk/webnak-cli
#   brew install webnak
class Webnak < Formula
  desc "Host and edit websites with Webnak, from your terminal"
  homepage "https://webnak.dev"
  version "${V}"
  license "MIT"

  on_macos do
    on_arm do
      url "${URL}/webnak_darwin_arm64"
      sha256 "$(sum webnak_darwin_arm64)"
    end
    on_intel do
      url "${URL}/webnak_darwin_amd64"
      sha256 "$(sum webnak_darwin_amd64)"
    end
  end

  on_linux do
    on_arm do
      url "${URL}/webnak_linux_arm64"
      sha256 "$(sum webnak_linux_arm64)"
    end
    on_intel do
      url "${URL}/webnak_linux_amd64"
      sha256 "$(sum webnak_linux_amd64)"
    end
  end

  def install
    bin.install Dir["webnak_*"].first => "webnak"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/webnak --version")
  end
end
RUBY
echo "wrote Formula/webnak.rb"
